struct Mutation{std::uintptr_t p,v;unsigned width;};for(auto x:{Mutation{0x100000,s.image+0x2295490,8},{0x100008,0,8},{(S().image+0x2c6c0c0+0x98),0,8},{(S().image+0x2c00d40),s.image+0x2308648,8},{(S().image+0x2bd6160),s.image+span,8},{(S().image+0x2bd6160),s.image-8,8},{(S().image+0x2bd6160),s.image+1,8},{(S().image+0x2c00d40+0xf8),(S().image+0x2bd6161),8},{0x10204,0x101,4},{0x100a8,0x1234,8},{0x10214,1,4},{0x10208,4,4},{0x1020c,1,4},{0x30040,1,4}}){auto v=Fixture();if(x.width==8)v.Put<std::uintptr_t>(x.p,x.v);else v.Put<std::uint32_t>(x.p,static_cast<std::uint32_t>(x.v));Check(!p::ReadPair(v,s,span,out),"altered chain refuses");}
